import React, { useState, useEffect } from "react";
import Banner from "./Banner";
import "../styles/main.css";

const Gallery = () => {
  const [images, setImages] = useState([]);

  useEffect(() => {
    // Fetch gallery images from backend API (admin uploaded images)
    // If backend not ready, fallback to static images
    const fetchImages = async () => {
      try {
        // Example: axios.get("/api/gallery") if backend exists
        // For now, fallback:
        const staticImages = Array.from({ length: 16 }, (_, i) => `/assets/GalleryImg${i + 1}.jpg`);
        setImages(staticImages);
      } catch (err) {
        console.error("Failed to load gallery images", err);
      }
    };
    fetchImages();
  }, []);

  return (
    <>
      <Banner />
      <div className="gallery-page">
        <h2>Gallery</h2>
        <div className="gallery-grid">
          {images.length === 0 ? (
            <p>No images available</p>
          ) : (
            images.map((img, idx) => (
              <div className="gallery-card" key={idx}>
                <img src={img} alt={`Gallery ${idx + 1}`} />
              </div>
            ))
          )}
        </div>
      </div>
    </>
  );
};

export default Gallery;
